// === Tab: mySketch ===
/**
 * Into the void
 * For the Weekly Creative Coding Challenge <<Downward Spiral>>
 * Join the discord! https://discord.gg/PrnrhZQrb9
 *
 * This is a shader practice, based on ahihi's Fiery Spiral https://www.shadertoy.com/view/XdSGzR
 * Playing around with the parameters to achieve a variety of different effects
 * Technically... this is not a spiral but just concentric circles, don't tell Raph
 */

let shaderProgram
let palettes = [
  ["#ed225d", "#3caf65", "#0d40bf", "#f5b800", "#2a2a2a"],
  ["#b30000", "#e6cf00", "#1283b3", "#fafafa", "#0a0a0a"],
  ["#606c38", "#283618", "#fefae0", "#dda15e", "#bc6c25"],
  ["#001427", "#708d81", "#f4d58d", "#bf0603", "#8d0801"],
  ["#3d5a80", "#98c1d9", "#e0fbfc", "#ee6c4d", "#293241"],
  ["#4464a1", "#62b6de", "#b3dce0", "#fafafa", "#ffc5c7", "#ee726b", "#cd1440"],
  ["#353535", "#3c6e71", "#ffffff", "#d9d9d9", "#284b63"],
  ["#0081a7", "#00afb9", "#fdfcdc", "#fed9b7", "#f07167"],
  ["#004b23", "#006400", "#007200", "#008000", "#38b000", "#9ef01a"],
  ["#0a1128", "#001f54", "#034078", "#1282a2", "#fefcfb"],
  ["#2d3142", "#bfc0c0", "#ffffff", "#ef8354", "#4f5d75"],
  ["#04151f", "#183a37", "#efd6ac", "#c44900", "#432534"],
  ["#ca9ce1", "#54defd", "#f1ffc4", "#ffcaaf", "#28587b"],
]
let palette

let currentPalette
let rotationSpeed, skewFactor, wobblyness, subDivisions, spiralFactor, spiralSpeed, xOff, yOff, blendColors, numColors, blendSame
let cw, ch

function setup() {
  cw = windowWidth
  ch = windowHeight
  createCanvas(cw, ch, WEBGL)
	pixelDensity(1)
  noStroke()
	shaderProgram = createShader(vert, frag)
  randomizeParameters()
}

function draw() {
  shader(shaderProgram)
  shaderProgram.setUniform("iResolution", [width * pixelDensity(), height * pixelDensity()])
  shaderProgram.setUniform("iTime", millis() / 1000.0)
  shaderProgram.setUniform("skewFactor", skewFactor)
  shaderProgram.setUniform("rotationSpeed", rotationSpeed)
  shaderProgram.setUniform("wobblyness", wobblyness)
  shaderProgram.setUniform("subDivisions", subDivisions)
  shaderProgram.setUniform("palette", currentPalette.flat())
  shaderProgram.setUniform("spiralFactor", spiralFactor)
  shaderProgram.setUniform("spiralSpeed", spiralSpeed)
  shaderProgram.setUniform("xOff", map((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), cw/4, cw*3/4, -0.2, 0.2, true))
  shaderProgram.setUniform("yOff", map((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), ch/4, ch*3/4, -0.2, 0.2, true))
  shaderProgram.setUniform("numColors", numColors)
  shaderProgram.setUniform("blendColors", blendColors)
	shaderProgram.setUniform("blendSame", blendSame)
  beginShape()
  vertex(-1, -1)
  vertex(1, -1)
  vertex(1, 1)
  vertex(-1, 1)
  endShape(CLOSE)
}

function mousePressed() {
  randomizeParameters()
}

function randomizeParameters() {
  // Pick random colors from the palette, and convert them to vec3
  numColors = floor(random(3, 5))
  let p = shuffle(random(palettes)).slice(0, numColors)
  currentPalette = [...p, ...p].slice(0, 5).map(hexToVec3)
  rotationSpeed = (random() ** 2) * random([-1, 1]) * 0.5
  skewFactor = (random() ** 2) * random([-1, 1]) * 0.7
  wobblyness = random(-0.4, 0)
  subDivisions = floor(2 + (random() ** 2) * 12)
  spiralFactor = 0.5 + (random() ** 2) * 1.5
  spiralSpeed = -(1 + (random() ** 2) * 2)
  xOff = random(-0.2, 0.2)
  yOff = random(-0.2, 0.2)
  blendColors = random() < 0.3
	blendSame = blendColors && random() < 0.2
}

function hexToVec3(hex) {
  hex = hex.replace("#", "")
  let r = parseInt(hex.substring(0, 2), 16) / 255.0
  let g = parseInt(hex.substring(2, 4), 16) / 255.0
  let b = parseInt(hex.substring(4, 6), 16) / 255.0
  return [r, g, b]
}


// === Tab: shader ===
const vert = `precision mediump float;

attribute vec3 aPosition;
varying vec2 vTexCoord;

void main() {
  vTexCoord = (aPosition.xy + 1.0) * 0.5;
  gl_Position = vec4(aPosition, 1.0);
}`

const frag = `
// fragment shader (spiral.frag)
precision mediump float;

#define PI 3.141592653589793
#define TAU 6.283185307179586

uniform vec2 iResolution; // Canvas size (width, height)
uniform float iTime; // Time in seconds
uniform vec3 palette[5]; // Pass 5 colors, even if we don't use them all
uniform float skewFactor; // Skew factor (positive means slanted to the right)
uniform float rotationSpeed; // Speed (and direction) of rotation
uniform float wobblyness; // Speed of the second "wobbly"
uniform float subDivisions; // Number of sub divisions
uniform float spiralFactor; // Shrink factor for concentric circles. Close to 0 means no spiral
uniform float spiralSpeed; // Speed at which concentric circles shrink or grow (depends on sign)
uniform float xOff;
uniform float yOff; // X and Y offsets for center
uniform int numColors; // Number of colors to use from the palette
uniform bool blendColors; // Whether to use solid colors or blend them
uniform bool blendSame; // To use a single color for the blends, giving it a soft gradient effect

vec3 getColor(int index) {
    // If index is negative, wrap around
    if(index < 0) index += (10 * numColors);
    // Get the modulo of the index to avoid out-of-bounds
    index = int(mod(float(index), float(numColors)));
    // GLSL 1 doesn't support variable indices :(
    // return palette[1];
    if(index == 0) return palette[0];
    else if(index == 1) return palette[1];
    else if(index == 2) return palette[2];
    else if(index == 3) return palette[3];
    else if(index == 4) return palette[4];
    return vec3(0.0);  // Default case (shouldn't be needed)
}

void main() {
    vec2 fragCoord = gl_FragCoord.xy;
    vec2 p = 2.0 * (0.5 * iResolution.xy - fragCoord.xy) / iResolution.xx;

    p.x += xOff;
    p.y -= yOff;
    p.y += skewFactor * p.x;

    // Move center slightly based on distance to center
    // float dist = length(p);
    // p.x += 5.0 * p.x * dist; //
    // p.y -= 4.1 * p.y * dist; // <--- Not at all what I expected, uncomment for some funky effects

    float angle = atan(p.y, p.x);
    float turn = (angle + PI) / TAU;


    float maxRadius = 2.0 * sqrt((iResolution.x / 2.0) * (iResolution.x / 2.0) + (iResolution.y / 2.0) * (iResolution.y / 2.0));
    float radius = pow(2.0 * p.x * p.x + 2.0 * p.y * p.y, 0.5);

    float rotation = (rotationSpeed / 10.0) * TAU * iTime;
    float turn_1 = turn + rotation;

    float turn_sub = mod(float(subDivisions) * turn_1, float(subDivisions));
    float sine = wobblyness * (1.0 - sin(10.0 * (pow(radius, 0.4) - 0.4 * iTime)));
    float turn_sine = turn_sub + sine;

    int i_turn = int(mod(float(numColors) * turn_sine, float(numColors)));
    int i_radius = int(2.5 * spiralFactor / pow(radius * 0.5, 0.6) + spiralSpeed * iTime);
    int i_color = int(mod(float(i_turn + i_radius), float(numColors)));

    vec3 colorA = getColor(i_color);
    vec3 colorB = getColor(i_color + 1);  // Mod to avoid out-of-bounds
		if (blendSame) {
		  colorB = getColor(0);
		}
    vec3 color = mix(colorA, colorB, fract(turn_sine + radius));
    if (!blendColors) {
        color = colorA;
    }

    color *= pow(radius, 0.35) * 0.9;
    // color *= 2.1 - radius;

    gl_FragColor = vec4(color, 1.0);
}
`

